// scripts/deploy_ethereumXReserve.js
const { ethers } = require("hardhat");

async function main() {
  const EthereumXReserve = await ethers.getContractFactory("EthereumXReserve");
  const ethereumXReserve = await EthereumXReserve.deploy();

  await ethereumXReserve.deployed();

  console.log("EthereumXReserve deployed to:", ethereumXReserve.address);
}

main()
  .then(() => process.exit(0))
  .catch((error) => {
    console.error(error);
    process.exit(1);
  });
